const items = $input.all();

return items.map(item => {
  const r = item.json;

  const sentrix_id = r.SentrixBarcode;
  const position = r.SentrixPosition;

  return {
    json: {
      sentrix_id,
      position,
      sample_id: r.SampleId,
      sample_name: r.SampleName,

      dataset_label: r.DatasetLabel,

      row: r.Row,
      column: r.Column,

      scanner_id: r.ScannerId,
      scanner_version: r.ScannerVersion,
      imaging_date: r.ImagingDate,
      sample_folder_path: r.SampleFolderPath,

      gtc_dir: `/volume1/ALLDATA/Scans/GTCs`,
      gtc_file_path: `/volume1/ALLDATA/Scans/GTCs/${sentrix_id}_${position}.gtc`,

      functional_qc_status: r["Functional QC Status"],
      control_qc_flag_codes: r["Control QC Flag Codes"] || null,

      autosomal_call_rate: r.AutosomalCallRate,
      call_rate: r.CallRate,
      log_r_dev: r.LogRDev,
      sex_estimate: r.SexEstimate,

      registration_score: r.RegistrationScore,

      qc_metrics: {
        StainingGreenQC: r.StainingGreenQC,
        StainingRedQC: r.StainingRedQC,
        ExtensionGreenQC: r.ExtensionGreenQC,
        ExtensionRedQC: r.ExtensionRedQC,
        HybridizationHighMediumQC: r.HybridizationHighMediumQC,
        HybridizationMediumLowQC: r.HybridizationMediumLowQC,
        RestorationQC: r.RestorationQC,
        TargetRemovalIQC: r.TargetRemovalIQC,
        StringencyQC: r.StringencyQC,
        NonSpecificBindingGreenQC: r.NonSpecificBindingGreenQC,
        NonSpecificBindingRedQC: r.NonSpecificBindingRedQC,
        NonPolymorphicGreenQC: r.NonPolymorphicGreenQC,
        NonPolymorphicRedQC: r.NonPolymorphicRedQC
      },

      raw_control_metrics: r
    }
  };
});

const input = $input.all();
const output = [];

for (const item of input) {
  const body = item.json.body ?? item.json;

  const runId = body.run_id;
  const processed = body.processed_sentrix_ids || [];
  const failed = body.failed_sentrix_ids || [];
  const log = body.log || null;

  if (!Array.isArray(processed) || processed.length === 0) {
    output.push({
      json: {
        status: 'nothing_processed',
        run_id: runId,
        failed_sentrix_ids: failed,
        log,
        message: 'processed_sentrix_ids boş geldi'
      }
    });
    continue;
  }

  for (const sentrix_id of processed) {
    output.push({
      json: {
        status: 'process_qc',
        run_id: runId,
        sentrix_id: String(sentrix_id),
        failed_sentrix_ids: failed,
        log,

        qc_dir: `/volume1/ALLDATA/Scans/.tmp_dragena/${sentrix_id}/qc_report`,
        qc_dir_server: `/mnt/koza_alldata/Scans/.tmp_dragena/${sentrix_id}/qc_report`,
        tmp_dir_server: `/mnt/koza_alldata/Scans/.tmp_dragena/${sentrix_id}`
      }
    });
  }
}

return output;

const raw =
  $json.stdout ??
  $json.data ??
  $json.output ??
  '';

const lines = String(raw)
  .split('\n')
  .map(line => line.trim())
  .filter(Boolean);

const jsonLine = [...lines]
  .reverse()
  .find(line => line.startsWith('{') && line.endsWith('}'));

if (!jsonLine) {
  return {
    json: {
      status: 'parse_failed',
      message: 'find_qc_xlsx_ssh çıktısında JSON satırı bulunamadı',
      raw_stdout: raw
    }
  };
}

const parsed = JSON.parse(jsonLine);

return {
  json: {
    ...$json,
    ...parsed
  }
};

const sentrixId =
  $json.sentrix_id ||
  $('parse_find_qc_xlsx').first().json.sentrix_id ||
  $('parse_find_qc_xlsx').first().json.sentrix ||
  null;

return [{
  json: {
    sentrix_id: sentrixId,
    qc_stdout: $json.stdout ?? ''
  }
}];

const items = $input.all().map(i => i.json);

// qc_stdout itemlarını sentrix_id bazında tut
const qcBySentrix = {};

for (const item of items) {
  if (item.qc_stdout && item.sentrix_id) {
    qcBySentrix[String(item.sentrix_id)] = item.qc_stdout;
  }
}

// Excel QC row itemları
const qcRows = items.filter(item =>
  item.SentrixBarcode &&
  item.SentrixPosition
);

const output = [];

for (const row of qcRows) {
  const sentrixId = String(row.SentrixBarcode);
  const qcText = qcBySentrix[sentrixId] || '';

  const regByPos = {};

  for (const line of qcText.split(/\r?\n/)) {
    const parts = line.trim().split(/\s+/);
    if (parts.length < 2) continue;

    const imageName = parts[0];

    // Her pozisyon için sadece 1. swath channel 1 alınacak
    if (!imageName.endsWith('_1_Swath1_Channel1')) continue;

    const pos = imageName.split('_')[0]; // R01C01
    const regScore = parseFloat(parts[1]);

    if (!isNaN(regScore)) {
      regByPos[pos] = regScore;
    }
  }

  output.push({
    json: {
      ...row,
      RegistrationScore: regByPos[row.SentrixPosition] ?? null,

      // test için geçici debug alanları
      _debug_text_length: qcText.length,
      _debug_reg_positions_count: Object.keys(regByPos).length,
      _debug_first_pos_value: regByPos['R01C01'] ?? null
    }
  });
}

return output;

